import{_ as l,C as c,o as t,c as p,a2 as s,b as r,w as a,a as n,E as o,a3 as d}from"./chunks/framework.CZqXuAiL.js";const y=JSON.parse(`{"title":"Architecture — Glacier Pack","description":"How Glacier Pack works under the hood — the standalone package format, service provider and route registration, the hub v2 pane contract, Glacier theme token compatibility, and Permission Manager's security model.","frontmatter":{"title":"Architecture — Glacier Pack","description":"How Glacier Pack works under the hood — the standalone package format, service provider and route registration, the hub v2 pane contract, Glacier theme token compatibility, and Permission Manager's security model.","outline":"deep"},"headers":[],"relativePath":"glacier-pack/architecture/overview.md","filePath":"glacier-pack/architecture/overview.md","lastUpdated":1786336917000}`),h={name:"glacier-pack/architecture/overview.md"};function u(g,e,m,b,f,k){const i=c("Mermaid");return t(),p("div",null,[e[3]||(e[3]=s(`<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><p>Glacier Pack is two things: a <strong>packaging format</strong> (46 self-contained addons that install onto Pterodactyl Panel v1.12.x without Blueprint) and a <strong>hub contract</strong> (one admin dashboard that hosts every addon&#39;s complete UI). This page explains both, plus the theme-compatibility layer and Permission Manager&#39;s security model.</p><hr><h2 id="the-standalone-package-format" tabindex="-1">The standalone package format <a class="header-anchor" href="#the-standalone-package-format" aria-label="Permalink to &quot;The standalone package format&quot;">​</a></h2><p>Every addon — including the hub itself — is a self-contained directory that mirrors the panel root exactly:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;addon-name&gt;/</span></span>
<span class="line"><span>├── README.md             # what it does, feature list</span></span>
<span class="line"><span>├── INSTALL.md            # install / uninstall guide</span></span>
<span class="line"><span>├── PanelFiles/           # mirrors /var/www/pterodactyl exactly</span></span>
<span class="line"><span>│   ├── app/              # controllers, models, services, providers</span></span>
<span class="line"><span>│   ├── config/           # the addon&#39;s config file</span></span>
<span class="line"><span>│   ├── database/         # migrations (with working down())</span></span>
<span class="line"><span>│   ├── resources/views/  # hub partials and client partials</span></span>
<span class="line"><span>│   ├── routes/           # action + API routes</span></span>
<span class="line"><span>│   └── public/ext/       # static JS/CSS assets</span></span>
<span class="line"><span>└── data/</span></span>
<span class="line"><span>    ├── install.sh        # idempotent installer</span></span>
<span class="line"><span>    ├── remove.sh         # remover</span></span>
<span class="line"><span>    └── patch-*.py        # optional marker-delimited blade patchers</span></span></code></pre></div><p>Naming is uniform across the family: kebab-case directories (<code>recycle-bin</code>), PascalCase namespace roots (<code>Pterodactyl\\Http\\Controllers\\Admin\\RecycleBin</code>), one service provider per addon (<code>Pterodactyl\\Providers\\&lt;Name&gt;ServiceProvider</code>), <code>&lt;snake_addon&gt;_*</code> database tables, <code>config/&lt;addon&gt;.php</code>, and <code>routes/admin-&lt;addon&gt;.php</code>.</p><h3 id="install-flow" tabindex="-1">Install flow <a class="header-anchor" href="#install-flow" aria-label="Permalink to &quot;Install flow&quot;">​</a></h3>`,8)),(t(),r(d,null,{default:a(()=>[o(i,{id:"mermaid-20",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22sudo%20bash%20data%2Finstall.sh%22%5D%20--%3E%20B%5B%22cp%20-a%20PanelFiles%2F.%3Cbr%2F%3Einto%20%24PTERODACTYL_DIRECTORY%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22Register%20service%20provider%20in%20config%2Fapp.php%3Cbr%2F%3E(marker%20comment%2C%20ordered%20anchor)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22Apply%20marker-delimited%20blade%20patches%3Cbr%2F%3E(asset%20loaders%2C%20permission%20groups)%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22php%20artisan%20migrate%20--force%20--no-interaction%22%5D%0A%20%20%20%20E%20--%3E%20F%5B%22Clear%20config%20%2F%20route%20%2F%20view%20%2F%20app%20caches%22%5D%0A%20%20%20%20F%20--%3E%20G%5B%22chown%20-R%20www-data%3Awww-data%22%5D%0A%20%20%20%20G%20--%3E%20H%5B%22Addon%20live%20%E2%80%94%20pane%20appears%20in%20the%20hub%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=s('<p>Every installer runs under <code>set -euo pipefail</code> and is <strong>idempotent</strong>: marker-delimited blocks (<code>&lt;!-- &lt;marker&gt;-block-start --&gt;</code>, <code>// &lt;marker&gt;</code> in <code>config/app.php</code>) are detected and skipped on re-run, so re-running after a panel update re-applies what the update overwrote without duplicating anything. Two addons deviate deliberately — Recycle Bin additionally patches the React frontend (requiring <code>yarn build:production</code>), and Node Stats ships a separate queue-worker installer.</p><p><strong>No core-file replacement.</strong> Patches are injected, never swapped. The one documented exception is Recycle Bin, which patches core panel files (marker <code>// pterodactyltrashbinpro</code>) — loudly documented in its own INSTALL.md.</p><hr><h2 id="service-provider-and-route-registration" tabindex="-1">Service provider and route registration <a class="header-anchor" href="#service-provider-and-route-registration" aria-label="Permalink to &quot;Service provider and route registration&quot;">​</a></h2><p>Each addon registers exactly one Laravel service provider, which merges its config, loads its routes, binds its view namespace and schedules any recurring work through the panel&#39;s scheduler — no cron or Kernel edits required (Recycle Bin&#39;s hourly purge, Resource Alerts&#39; per-minute sampling, Backup Pro&#39;s run-due/check-sync/prune commands and Permission Manager&#39;s hourly <code>permgr:sync</code> all wire in this way).</p><p>After hub v2 conversion, an addon&#39;s route table contains <strong>no <code>GET /admin/&lt;addon&gt;</code> page routes</strong> — only action endpoints (POST/DELETE) and API routes. The page routes were removed with the original admin pages; the endpoints stayed because hub forms post to them. Authorization checks live on every controller method, input is validated server-side, and Blade output is escaped.</p><hr><h2 id="the-hub-v2-architecture" tabindex="-1">The hub v2 architecture <a class="header-anchor" href="#the-hub-v2-architecture" aria-label="Permalink to &quot;The hub v2 architecture&quot;">​</a></h2><p>The hub is a single root-admin-guarded controller and one standalone page (its own chrome, not AdminLTE) driven by a plain config registry (<code>config/glacier-pack.php</code>) listing all 46 addons with their slug, name, description, pack, icon and pane view.</p>',9)),(t(),r(d,null,{default:a(()=>[o(i,{id:"mermaid-44",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20Admin%20as%20Root%20admin%0A%20%20%20%20participant%20Hub%20as%20Hub%20controller%3Cbr%2F%3E%2Fadmin%2Fglacier-pack%0A%20%20%20%20participant%20View%20as%20Addon%20pane%20partial%3Cbr%2F%3Eadmin.%3Cdir%3E.hub%5B-sub%5D%0A%20%20%20%20participant%20EP%20as%20Addon%20endpoint%3Cbr%2F%3E(existing%20POST%2FDELETE%20route)%0A%0A%20%20%20%20Admin-%3E%3EHub%3A%20GET%20%3Fa%3D%3Cslug%3E%26p%3D%3Csub%3E%0A%20%20%20%20Hub-%3E%3EHub%3A%20authorizeRootAdmin%20(explicit%20403%20guard)%0A%20%20%20%20Hub-%3E%3EView%3A%20include%20if%20View%3A%3Aexists%20(graceful%20fallback)%0A%20%20%20%20View--%3E%3EAdmin%3A%20full%20addon%20UI%20in%20gp-native%20%2F%20gp-*%20markup%0A%20%20%20%20Admin-%3E%3EEP%3A%20POST%20form%20%2B%20hidden%20_hub%20return%20URL%0A%20%20%20%20EP-%3E%3EEP%3A%20validate%20_hub%20starts%20with%20%2Fadmin%2Fglacier-pack%0A%20%20%20%20EP--%3E%3EAdmin%3A%20redirect%20to%20_hub%20(same%20pane%2C%20%3Fsaved%3D1)%3Cbr%2F%3Eor%20back%20with%20%24errors%20on%20validation%20failure%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=s(`<p>Key mechanics:</p><ul><li><strong>Pane resolution</strong> — <code>?a=&lt;slug&gt;</code> renders <code>admin.&lt;dir&gt;.hub</code>; <code>?p=&lt;sub&gt;</code> renders <code>admin.&lt;dir&gt;.hub-&lt;sub&gt;</code>, <code>View::exists</code>-checked with fallback to the main pane for unknown subs. The <code>p</code> parameter is restricted to <code>[a-z0-9-]</code>.</li><li><strong>Sub-tabs</strong> — a multi-page partial declares its own tabs by including the shell&#39;s <code>glacier-pack::subtabs</code> component with a label/<code>p</code> list.</li><li><strong>Self-sufficient partials</strong> — the hub passes only <code>$gp</code> (registry meta) and <code>$gpSub</code> (active sub); each partial reads its own data inline through the same services and models the addon&#39;s original controllers used.</li><li><strong>Styling</strong> — original Bootstrap-ish markup is kept and wrapped in <code>&lt;div class=&quot;gp-native&quot;&gt;</code>, which the hub stylesheet themes to match (boxes, tables, forms, buttons, labels, alerts, pagination, nav-tabs, small-boxes, callouts). Anything new uses the shared <code>gp-*</code> component classes.</li><li><strong>Uniform POST flow</strong> — every form and row action (delete / toggle / run / create) carries the full return URL in <code>_hub</code>. Controllers validate it is a local <code>/admin/glacier-pack</code> path (403 otherwise) and redirect there. Validation failures redirect back automatically and render in the hub shell&#39;s error callout.</li><li><strong>Zero dependencies</strong> — the hub has no database tables, loads no external CDN assets, and uses inline SVG icons.</li></ul><hr><h2 id="glacier-theme-compatibility" tabindex="-1">Glacier theme compatibility <a class="header-anchor" href="#glacier-theme-compatibility" aria-label="Permalink to &quot;Glacier theme compatibility&quot;">​</a></h2><p>All client-facing addon CSS consumes the Glacier theme&#39;s design tokens through <code>var(--gl-*, fallback)</code> chains:</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">color: var(--gl-ink, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">#e5e7eb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">background: var(--gl-surface, </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">#1f242b</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">border-radius</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: var(--gl-radius, 8px);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">border: 1px solid var(--gl-border, </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">#2e343d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Glacier emits its tokens on <code>:root</code> (plus <code>html[data-glacier=&quot;light&quot;]</code> overrides), so a plain <code>var(--gl-*, fallback)</code> inherits the theme automatically when it is installed and is a no-op when it is not. The fallback always equals the addon&#39;s own shipped value, so the standalone look is pixel-identical without Glacier.</p><table tabindex="0"><thead><tr><th>Purpose</th><th>Token</th><th>Purpose</th><th>Token</th></tr></thead><tbody><tr><td>page background</td><td><code>--gl-bg</code></td><td>accent</td><td><code>--gl-accent</code></td></tr><tr><td>surface / cards</td><td><code>--gl-surface</code></td><td>accent fill</td><td><code>--gl-accent-soft</code></td></tr><tr><td>elevated (modals)</td><td><code>--gl-elevated</code></td><td>success / warning / danger</td><td><code>--gl-success</code> / <code>--gl-warning</code> / <code>--gl-danger</code></td></tr><tr><td>primary / secondary text</td><td><code>--gl-ink</code> / <code>--gl-muted</code></td><td>radius</td><td><code>--gl-radius</code> / <code>--gl-radius-sm</code> / <code>--gl-radius-lg</code></td></tr><tr><td>borders</td><td><code>--gl-border</code> / <code>--gl-hairline</code></td><td>container w/ opacity</td><td><code>--gl-container-bg</code></td></tr></tbody></table><p>Two scope rules keep this safe: only <strong>client-facing</strong> styles participate (server pages, account area, login page — never AdminLTE admin pages or the hub), and only presentational values route through tokens — JavaScript behavior, class names and structure are untouched.</p><hr><h2 id="permission-manager-s-security-model" tabindex="-1">Permission Manager&#39;s security model <a class="header-anchor" href="#permission-manager-s-security-model" aria-label="Permalink to &quot;Permission Manager&#39;s security model&quot;">​</a></h2><p>Permission Manager is the family&#39;s delegation layer, designed so staff can never widen their own access from any angle:</p>`,12)),(t(),r(d,null,{default:a(()=>[o(i,{id:"mermaid-191",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Root%5B%22Root%20admin%20(hub%20pane)%22%5D%0A%20%20%20%20%20%20%20%20ROLES%5B%22Roles%20%E2%80%94%20pages%2C%20scope%2C%3Cbr%2F%3Ebuild%20edit%2C%20subuser%20permissions%22%5D%0A%20%20%20%20%20%20%20%20MEMBERS%5B%22Members%20%E2%80%94%20user%20%2B%20role%2C%3Cbr%2F%3Escoped%20assignments%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20Staff%5B%22Staff%20user%20(root_admin%20%3D%200%2C%20always)%22%5D%0A%20%20%20%20%20%20%20%20AREA%5B%22%2Fadmin%2Fstaff%3Cbr%2F%3EStaffAuthenticate%20%2B%20per-route%20StaffPagePermission%22%5D%0A%20%20%20%20%20%20%20%20SUB%5B%22Real%20Pterodactyl%20subusers%3Cbr%2F%3Eon%20in-scope%20servers%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20ROLES%20--%3E%20MEMBERS%0A%20%20%20%20MEMBERS%20--%3E%20AREA%0A%20%20%20%20MEMBERS%20--%3E%7Cpermgr%3Async%2C%20hourly%7C%20SUB%0A%20%20%20%20SUB%20--%3E%7Cenforced%20natively%3Cbr%2F%3Eby%20the%20panel%7C%20PANEL%5B%22Client%20panel%22%5D%0A"})]),fallback:a(()=>[...e[2]||(e[2]=[n(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=s('<ul><li><strong>No <code>root_admin</code>, ever.</strong> Member accounts keep <code>root_admin = 0</code> for their lifetime, so the stock <code>AdminAuthenticate</code> middleware keeps every core <code>/admin/*</code> page closed to them.</li><li><strong>Fail-closed staff area.</strong> <code>/admin/staff</code> runs its own middleware (<code>StaffAuthenticate</code> plus a per-route <code>StaffPagePermission</code> gate) — never the stock admin gate. A staff route registered without a page-permission parameter answers 403.</li><li><strong>Server-side scope only.</strong> All scope decisions are computed from the role row and assignment tables. Request input can narrow a search but never widen a scope, and out-of-scope IDs answer 403 rather than 404 so existence is not leaked.</li><li><strong>No self-management capability.</strong> The staff route group contains no routes at all for managing roles, members, assignments or provisioning — the capability does not exist for staff.</li><li><strong>Native enforcement on servers.</strong> On every in-scope server the addon maintains a <em>real</em> Pterodactyl subuser with exactly the role&#39;s permission set (default: console, power actions, file read). Client-panel access is enforced by Pterodactyl itself — there is no custom proxy to bypass. The addon only ever touches subuser rows it created (tracked in <code>permgr_provisioned_subusers</code>); subusers created by server owners are never adopted, edited or deleted.</li><li><strong>Full audit trail.</strong> Every root management write and every staff write is recorded with actor, action, target, payload and IP.</li><li><strong>Reconciliation.</strong> <code>php artisan permgr:sync</code> (scheduled hourly) reconciles provisioned subusers after role edits, deactivations and scope changes.</li></ul><p>Root admins may open <code>/admin/staff</code> as a clearly-marked full-scope preview; management itself always happens in the hub pane.</p><hr><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next?&quot;">​</a></h2><ul><li><strong><a href="./../getting-started/installation">Installation →</a></strong> — put it on a panel.</li><li><strong><a href="./../configuration/reference">Configuration Reference →</a></strong> — every setting, every default.</li><li><strong><a href="./../user-guide/dashboard">The Hub Dashboard →</a></strong> — the contract from the admin&#39;s chair.</li></ul>',5))])}const E=l(h,[["render",u]]);export{y as __pageData,E as default};
